/**
 * Acceptance tests (protected): every Worker alert/failure line carries the
 * container release and the stable log-query URL.
 *
 * Contract under test: the readiness-transition line already stamps
 * `release` (strict lowercase-hex git SHA from /readyz `build_revision`, or
 * the visible `"unknown"` bucket) plus `log_url`. The failure lines below
 * must carry the same two fields, with the existing identifying fields
 * preserved. On the current baseline they do not, so these tests FAIL
 * (RED) until the builder stamps the fields; do not edit this file to make
 * an implementation pass — fix the implementation.
 *
 * Lines in scope (wrangler/src/index.ts at the baseline):
 * - :436 `metrics_scrape_token_misconfigured` (JSON today, fields absent)
 * - :493 `container_probe_failed` (JSON today, fields absent)
 * - :1337 `container_keepalive_arm_failed` (JSON today, fields absent)
 * - :1369 "two-bot /readyz unhealthy: <status>" (plain text today)
 * - :1382/:1385/:1412 "two-bot keepalive probe failed" (plain text today;
 *   the past-deadline scenario may settle through either the :1382 branch
 *   or the :1412 catch — the asserted line contract is identical, so the
 *   test is race-proof by construction)
 * - :1683/:1685 `metrics_alert_webhook_failed` (JSON today, fields absent)
 * - :1711 `container_unready_webhook_failed`, plus its :1715 catch twin
 *   (same event, `status: null`; stamping one and not the other would
 *   leave the outcome half-done)
 *
 * Shape the builder must produce:
 * - Every line above is a single JSON object line (Workers Logs extracts
 *   fields from JSON, not from prose). Plain-text lines convert to JSON
 *   keeping a string identifier containing `unhealthy` (for :1369, with
 *   the numeric `status` preserved) or `probe_failed`/`probe failed` (for
 *   the probe-failure lines).
 * - `release` matches /^[0-9a-f]{7,40}$/ or is exactly `"unknown"`. Where
 *   the same keepalive tick parsed a /readyz `build_revision`, the line
 *   carries that SHA. A probe that yielded no parsed body this tick
 *   carries `"unknown"` — never a previous image's SHA (the :1375-1377
 *   reset exists precisely so a failed probe cannot reuse one), and the
 *   :1369 line (logged before the body is read) is either this tick's
 *   SHA or `"unknown"`, never the stale previous one.
 * - `log_url` is exactly the stable LOG_QUERY_URL docs URL.
 * - No secrets, URLs, headers or bodies are logged: a hostile
 *   `build_revision`, webhook binding, error text or probe body never
 *   reaches a line, and no string value other than `log_url` is
 *   URL-shaped.
 *
 * Existing exact-shape pins the builder must update when converting the
 * plain-text lines (this file stays frozen):
 * - test/container.test.ts — the exact
 *   `JSON.stringify({ event: "container_keepalive_arm_failed" })` log
 *   inclusion, and the exact `"two-bot /readyz unhealthy: 503"` inclusions.
 * Substring/JSON pins that keep passing unchanged: test/health-probes.test.ts
 * (misconfigured line names the event and the 32 minimum, never the token)
 * and the `events()[1]` webhook-failure pins in test/container.test.ts.
 *
 * Runtime storage is in-memory; all env values are synthetic. No Discord,
 * database, deployed Worker, Docker daemon or secret bindings are contacted.
 * Run: node --import ./test/cloudflare-loader.mjs --test test/alert-line-release-acceptance.test.ts
 */
import { test, type TestContext } from "node:test";
import assert from "node:assert/strict";
import { DatabaseSync } from "node:sqlite";
import worker, { TwoBotContainer, type Env } from "../src/index.ts";
import { OWNER_KEY } from "../src/ownership.ts";
import { LOG_QUERY_URL } from "../src/alert-rules.ts";
import { metricsBody } from "./fixtures/metrics.ts";

const ID = "deployment-A";
const CONTROL_TOKEN = "synthetic-control-token-not-a-secret-12345";
const ACTIVE_OWNER = {
  deploymentId: ID, epoch: 1, phase: "active", actor: "fixture-operator",
  timestamp: "2026-10-01T00:00:00.000Z", oldEpoch: 0, oldDeploymentId: null,
};
// Webhook id/token stay separate constants so no-echo assertions never pass
// a URL-shaped string to a substring check (CodeQL
// js/incomplete-url-substring-sanitization). WEBHOOK_URL keeps the exact
// destination the production code posts to.
const WEBHOOK_ID = "123456789012345678";
const WEBHOOK_TOKEN = "synthetic-token-not-a-secret";
const WEBHOOK_URL = `https://discord.com/api/webhooks/${WEBHOOK_ID}/${WEBHOOK_TOKEN}`;
const BODY_MARKER = "synthetic-secret-body-marker";
const DISCORD_TOKEN = "synthetic-discord-token";
const DATABASE_VALUE = "synthetic-database-value";

/** Two distinct strict release tokens (40 lowercase hex). */
const RELEASE_A = "a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1";
const RELEASE_B = "b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2b2";
const SHA_OR_UNKNOWN = /^(?:[0-9a-f]{7,40}|unknown)$/;

const WORKER_ENV = {
  CF_VERSION_METADATA: { id: ID },
  OWNERSHIP_CONTROL_TOKEN: CONTROL_TOKEN,
  DISCORD_TOKEN,
  DATABASE_URL: DATABASE_VALUE,
  GUILD_ID: "111222333444555666",
  KEEPALIVE_SECONDS: "60",
  // Readiness stays silent unless a test opts into the transition.
  UNREADY_ALERT_FAILURES: "1000",
  OPS_ALERT_WEBHOOK_URL: WEBHOOK_URL,
  OPS_ALERT_FORWARDING: "on",
};

type ContainerFixture = () => Promise<Response>;

async function harness(t: TestContext, options: {
  env?: Partial<typeof WORKER_ENV>;
  webhook?: () => Promise<Response>;
} = {}) {
  const database = new DatabaseSync(":memory:");
  t.after(() => database.close());
  const logs: string[] = [];
  for (const method of ["log", "warn", "error"] as const) {
    t.mock.method(console, method, (...args: unknown[]) => {
      logs.push(args.map(String).join(" "));
    });
  }
  const values = new Map<string, unknown>([[OWNER_KEY, ACTIVE_OWNER]]);
  const gates: Promise<unknown>[] = [];
  const runtime = {
    running: false,
    async destroy() { this.running = false; },
    start() { this.running = true; },
    monitor: () => new Promise<void>(() => {}),
    getTcpPort: () => ({
      async fetch() { throw new Error("fixture TCP must not be reached: containerFetch is mocked"); },
    }),
  };
  const ctx = {
    exports: { ContainerProxy: () => ({ fetch: () => { throw new Error("unexpected outbound request"); } }) },
    id: { toString: () => "synthetic-do-id" },
    container: runtime,
    storage: {
      get: async (key: string) => values.get(key),
      put: async (key: string | Record<string, unknown>, value?: unknown) => {
        if (typeof key === "string") values.set(key, value);
        else for (const [k, v] of Object.entries(key)) values.set(k, v);
      },
      delete: async (key: string) => values.delete(key),
      kv: {
        get: (key: string) => values.get(key),
        put: (key: string, value: unknown) => { values.set(key, value); },
        delete: (key: string) => values.delete(key),
      },
      sql: {
        exec(query: string, ...bindings: (string | number | null)[]) {
          return database.prepare(query).all(...bindings);
        },
      },
      setAlarm: async () => {},
      deleteAlarm: async () => {},
      sync: async () => {},
    },
    blockConcurrencyWhile<T>(callback: () => Promise<T>) {
      const promise = callback();
      gates.push(promise);
      return promise;
    },
  };
  const bot = new TwoBotContainer(
    ctx as unknown as DurableObjectState<{}>,
    { ...WORKER_ENV, ...options.env } as unknown as Env,
  );
  await Promise.all(gates);

  let probe: ContainerFixture = async () =>
    Response.json({ ready: true, build_revision: RELEASE_B }, { status: 200 });
  let metrics: ContainerFixture = async () => new Response(metricsBody());
  t.mock.method(bot, "containerFetch", (input: unknown) => {
    const path = new URL(typeof input === "string" ? input : (input as Request).url).pathname;
    if (path === "/metrics") return metrics();
    if (path === "/readyz") return probe();
    return Promise.resolve(new Response(null, { status: 200 }));
  });

  const posts: string[] = [];
  t.mock.method(globalThis, "fetch", async (url: URL, init?: RequestInit) => {
    const body = typeof init?.body === "string" ? JSON.parse(init.body) as { content?: string } : {};
    posts.push(body.content ?? "");
    void url;
    return options.webhook ? options.webhook() : new Response(null, { status: 204 });
  });

  const tick = async () => {
    await bot.onStart();
    const [pending] = await bot.listSchedules<{ startedAt: number }>("keepalive");
    assert.ok(pending, "keepalive armed before tick");
    await bot.keepalive(pending.payload!, pending);
  };

  return {
    bot, logs, values, posts, tick, ctx,
    setProbe: (next: ContainerFixture) => { probe = next; },
    setMetrics: (next: ContainerFixture) => { metrics = next; },
  };
}

/** Parse one line as JSON and assert the two stamped fields; returns the record. */
function assertCarries(line: string, label: string): Record<string, unknown> {
  let record: Record<string, unknown>;
  try {
    record = JSON.parse(line) as Record<string, unknown>;
  } catch {
    assert.fail(`${label}: line is not a single JSON object: ${line}`);
  }
  assert.ok(
    typeof record["release"] === "string" && SHA_OR_UNKNOWN.test(record["release"]),
    `${label}: release must be a strict SHA token or "unknown", got ${JSON.stringify(record["release"])} in: ${line}`,
  );
  assert.equal(record["log_url"], LOG_QUERY_URL, `${label}: log_url must be the stable log-query URL in: ${line}`);
  return record;
}

function findLines(logs: string[], pattern: RegExp): string[] {
  return logs.filter((line) => pattern.test(line));
}

function singleLine(logs: string[], pattern: RegExp, label: string): string {
  const found = findLines(logs, pattern);
  assert.ok(found.length >= 1, `${label}: no matching line in: ${JSON.stringify(logs)}`);
  return found[0]!;
}

/** No synthetic secret/body/binding marker may appear on any captured line. */
function assertNoEcho(logs: string[], extras: string[] = []) {
  const markers = [BODY_MARKER, DISCORD_TOKEN, DATABASE_VALUE, WEBHOOK_ID, WEBHOOK_TOKEN, ...extras];
  for (const marker of markers) {
    assert.ok(logs.every((line) => !line.includes(marker)), `marker ${JSON.stringify(marker)} leaked into a log line`);
  }
}

/** In the named record, `log_url` is the only URL-shaped string value. */
function assertOnlyLogUrlIsUrl(record: Record<string, unknown>, label: string) {
  for (const [key, value] of Object.entries(record)) {
    if (typeof value !== "string" || key === "log_url") continue;
    assert.ok(!value.includes("://"), `${label}: field ${key} carries a URL: ${value}`);
  }
}

// Control (GREEN on the baseline): the log-query constant itself is the
// stable public docs URL every line must stamp.
test("control: LOG_QUERY_URL stays the stable public docs URL", () => {
  assert.equal(LOG_QUERY_URL, "https://developers.cloudflare.com/workers/observability/logs/workers-logs/");
});

// Control (GREEN on the baseline): the readiness-transition line already
// carries both fields and must keep doing so.
test("control: readiness-transition line carries the probe release and log URL", async (t) => {
  const h = await harness(t, { env: { UNREADY_ALERT_FAILURES: "1" } });
  h.setProbe(async () => Response.json(
    { ready: false, build_revision: RELEASE_B }, { status: 503 },
  ));
  await h.tick();
  const line = singleLine(h.logs, /container_unready_alert/, "readiness transition");
  const record = assertCarries(line, "container_unready_alert");
  assert.equal(record["release"], RELEASE_B, "transition line carries this tick's probe SHA");
  assertNoEcho(h.logs);
});

test("metrics_scrape_token_misconfigured carries release and log URL, never the token", async (t) => {
  const logs: string[] = [];
  t.mock.method(console, "error", (...args: unknown[]) => {
    logs.push(args.map(String).join(" "));
  });
  const short = "short-token";
  const env = {
    REDIRECT_MAPPINGS_JSON: "[]",
    REDIRECT_FALLBACK_CODE: "fallbackCode",
    CF_VERSION_METADATA: { id: "synthetic-probe-deployment" },
    METRICS_SCRAPE_TOKEN: short,
    TWO_BOT: { getByName: () => ({ fetch: async () => new Response("must not forward") }) },
  } as unknown as Env;
  const ctx = { waitUntil() {} } as unknown as ExecutionContext;
  const res = await worker.fetch(
    new Request("https://probe.invalid/ops/metrics", { headers: { authorization: `Bearer ${short}` } }),
    env, ctx,
  );
  assert.equal(res.status, 404);
  await res.text();
  // The misconfiguration line is once-per-isolate; this is the only test in
  // this file that trips it.
  const line = singleLine(logs, /metrics_scrape_token_misconfigured/, "short-token line");
  const record = assertCarries(line, "metrics_scrape_token_misconfigured");
  assert.equal(record["event"], "metrics_scrape_token_misconfigured");
  assert.equal(record["reason"], "token_below_minimum_length", "existing identifying fields stay");
  assert.equal(record["minimum_length"], 32, "existing identifying fields stay");
  assertOnlyLogUrlIsUrl(record, "metrics_scrape_token_misconfigured");
  assertNoEcho(logs, [short, "Bearer"]);
});

test("container_probe_failed carries release and log URL, never the upstream error text", async (t) => {
  const logs: string[] = [];
  t.mock.method(console, "error", (...args: unknown[]) => {
    logs.push(args.map(String).join(" "));
  });
  const env = {
    REDIRECT_MAPPINGS_JSON: "[]",
    REDIRECT_FALLBACK_CODE: "fallbackCode",
    CF_VERSION_METADATA: { id: "synthetic-probe-deployment" },
    TWO_BOT: {
      getByName: () => ({
        fetch: async () => new Response(BODY_MARKER, { status: 500, headers: { "content-type": "text/plain" } }),
      }),
    },
  } as unknown as Env;
  const ctx = { waitUntil() {} } as unknown as ExecutionContext;
  const res = await worker.fetch(new Request("https://probe.invalid/readyz"), env, ctx);
  assert.equal(res.status, 500);
  await res.text();
  const line = singleLine(logs, /container_probe_failed/, "probe-failed edge line");
  const record = assertCarries(line, "container_probe_failed");
  assert.equal(record["event"], "container_probe_failed");
  assert.equal(record["error_class"], "container_unavailable", "existing identifying fields stay");
  assertOnlyLogUrlIsUrl(record, "container_probe_failed");
  assertNoEcho(logs);
});

test("container_keepalive_arm_failed carries release and log URL, never the scheduling error", async (t) => {
  const h = await harness(t);
  const exec = h.ctx.storage.sql.exec;
  t.mock.method(h.ctx.storage.sql, "exec", (query: string, ...bindings: (string | number | null)[]) => {
    if (/SELECT \* FROM container_schedules WHERE callback =/.test(query)
      || /INSERT OR REPLACE INTO container_schedules/.test(query)) {
      throw new Error(`synthetic scheduling failure ${DISCORD_TOKEN} ${WEBHOOK_URL} ${BODY_MARKER}`);
    }
    return exec(query, ...bindings);
  });
  await h.bot.onStart();
  const line = singleLine(h.logs, /container_keepalive_arm_failed/, "arm-failed line");
  const record = assertCarries(line, "container_keepalive_arm_failed");
  assert.equal(record["event"], "container_keepalive_arm_failed");
  assertOnlyLogUrlIsUrl(record, "container_keepalive_arm_failed");
  assertNoEcho(h.logs);
});

test("readyz-unhealthy line carries release and log URL with status, never the stale previous SHA", async (t) => {
  const h = await harness(t);
  // Tick 1: healthy probe from image A primes the DO's remembered release.
  h.setProbe(async () => Response.json(
    { ready: true, build_revision: RELEASE_A }, { status: 200 },
  ));
  await h.tick();
  const at = h.logs.length;
  // Tick 2: the replaced image B answers 503. The unhealthy line is logged
  // before the body is read, so it may carry B (if the builder moves or
  // refreshes it) or "unknown" — never the stale A.
  h.setProbe(async () => Response.json(
    { ready: false, build_revision: RELEASE_B }, { status: 503 },
  ));
  await h.tick();
  const line = singleLine(h.logs.slice(at), /unhealthy/, "readyz-unhealthy line");
  const record = assertCarries(line, "readyz unhealthy");
  assert.equal(record["status"], 503, "the observed probe status stays on the line");
  assert.notEqual(record["release"], RELEASE_A, "a failed probe must not reuse the previous image's SHA");
  assert.ok(
    record["release"] === RELEASE_B || record["release"] === "unknown",
    `release must be this tick's SHA or "unknown", got ${JSON.stringify(record["release"])}`,
  );
  assertOnlyLogUrlIsUrl(record, "readyz unhealthy");
  assertNoEcho(h.logs);
});

test("keepalive probe-failed line (transport throws) carries release and log URL as unknown", async (t) => {
  const h = await harness(t);
  h.setProbe(async () => Response.json(
    { ready: true, build_revision: RELEASE_A }, { status: 200 },
  ));
  await h.tick();
  const at = h.logs.length;
  h.setProbe(async () => { throw new Error(`timeout ${DISCORD_TOKEN} ${BODY_MARKER}`); });
  await h.tick();
  const line = singleLine(h.logs.slice(at), /probe[ _]failed/, "probe-failed (throw) line");
  const record = assertCarries(line, "keepalive probe failed");
  assert.equal(record["release"], "unknown",
    "no probe body was parsed this tick: never the previous image's SHA");
  assertOnlyLogUrlIsUrl(record, "keepalive probe failed");
  assertNoEcho(h.logs);
});

test("keepalive probe-failed line (oversized body) carries release and log URL as unknown", async (t) => {
  const h = await harness(t);
  h.setProbe(async () => new Response(BODY_MARKER + "x".repeat(70 * 1024), {
    status: 200, headers: { "content-type": "application/json" },
  }));
  await h.tick();
  const line = singleLine(h.logs, /probe[ _]failed/, "probe-failed (oversized) line");
  const record = assertCarries(line, "keepalive probe failed (oversized)");
  assert.equal(record["release"], "unknown", "an over-cap body is a failed probe: no release to claim");
  assertNoEcho(h.logs);
});

test("keepalive probe-failed line (completes past deadline) carries release and log URL as unknown", async (t) => {
  const h = await harness(t);
  const ac = new AbortController();
  const realTimeout = AbortSignal.timeout;
  t.mock.method(AbortSignal, "timeout", (ms: number) => (ms === 6000 ? ac.signal : realTimeout(ms)));
  let pulls = 0;
  h.setProbe(async () => new Response(new ReadableStream<Uint8Array>({
    pull(controller) {
      pulls += 1;
      if (pulls === 1) {
        controller.enqueue(new TextEncoder().encode(
          JSON.stringify({ ready: true, build_revision: RELEASE_B }),
        ));
        return;
      }
      // Complete the body and trip the deadline in the same pull: the read
      // finishes, but the probe signal is aborted before the tick trusts it.
      controller.close();
      ac.abort();
    },
  }, { highWaterMark: 0 }), { status: 200, headers: { "content-type": "application/json" } }));
  await h.tick();
  const line = singleLine(h.logs, /probe[ _]failed/, "probe-failed (past deadline) line");
  const record = assertCarries(line, "keepalive probe failed (past deadline)");
  assert.equal(record["release"], "unknown",
    "a probe that only completed past its deadline is no release evidence");
  assertNoEcho(h.logs);
});

for (const failure of [500, "throw"] as const) {
  test(`container_unready_webhook_failed (${failure}) carries the probe release and log URL`, async (t) => {
    const h = await harness(t, {
      env: { UNREADY_ALERT_FAILURES: "1" },
      webhook: async () => {
        if (failure === "throw") throw new Error(`fetch failed: ${WEBHOOK_URL} ${BODY_MARKER}`);
        return new Response(BODY_MARKER, { status: failure });
      },
    });
    h.setProbe(async () => Response.json(
      { ready: false, build_revision: RELEASE_B }, { status: 503 },
    ));
    await h.tick();
    const line = singleLine(h.logs, /container_unready_webhook_failed/, "readiness webhook-failed line");
    const record = assertCarries(line, "container_unready_webhook_failed");
    assert.equal(record["event"], "container_unready_webhook_failed");
    assert.equal(record["notification"], "container_unready_alert", "existing identifying fields stay");
    assert.equal(record["status"], failure === "throw" ? null : failure, "existing identifying fields stay");
    assert.equal(record["release"], RELEASE_B, "the same tick's probe SHA rides the webhook-failure line");
    assertOnlyLogUrlIsUrl(record, "container_unready_webhook_failed");
    assertNoEcho(h.logs);
  });
}

function firingMetrics(): string {
  return metricsBody(3).replace(
    'two_bot_job_last_error_class{job="rank",class="database"} 0',
    'two_bot_job_last_error_class{job="rank",class="database"} 1',
  );
}

for (const failure of [500, "throw"] as const) {
  test(`metrics_alert_webhook_failed (${failure}) carries the probe release and log URL`, async (t) => {
    const h = await harness(t, {
      webhook: async () => {
        if (failure === "throw") throw new Error(`fetch failed: ${WEBHOOK_URL} ${BODY_MARKER}`);
        return new Response(BODY_MARKER, { status: failure });
      },
    });
    h.setProbe(async () => Response.json(
      { ready: true, build_revision: RELEASE_B }, { status: 200 },
    ));
    h.setMetrics(async () => new Response(firingMetrics()));
    let line = "";
    for (let i = 0; i < 3 && !line; i++) {
      await h.tick();
      line = findLines(h.logs, /metrics_alert_webhook_failed/)[0] ?? "";
    }
    assert.ok(line, `metrics webhook-failed line never appeared in: ${JSON.stringify(h.logs)}`);
    const record = assertCarries(line, "metrics_alert_webhook_failed");
    assert.equal(record["event"], "metrics_alert_webhook_failed");
    assert.equal(record["status"], failure === "throw" ? null : failure, "existing identifying fields stay");
    assert.equal(record["release"], RELEASE_B, "the same tick's probe SHA rides the webhook-failure line");
    assertOnlyLogUrlIsUrl(record, "metrics_alert_webhook_failed");
    assertNoEcho(h.logs);
  });
}

test("no-secret shape: a hostile build_revision lands in the unknown bucket, never echoed", async (t) => {
  const h = await harness(t, {
    env: { UNREADY_ALERT_FAILURES: "1" },
    webhook: async () => new Response(BODY_MARKER, { status: 500 }),
  });
  const hostileRevision = "postgres://user:hunter2@db.internal/app";
  h.setProbe(async () => Response.json(
    { ready: false, build_revision: hostileRevision, error: BODY_MARKER }, { status: 503 },
  ));
  await h.tick();
  const named: [string, RegExp][] = [
    ["readyz unhealthy", /unhealthy/],
    ["container_unready_webhook_failed", /container_unready_webhook_failed/],
  ];
  for (const [label, pattern] of named) {
    const line = singleLine(h.logs, pattern, label);
    const record = assertCarries(line, label);
    assert.equal(record["release"], "unknown",
      `${label}: a non-token build_revision must bucket as unknown, not echo`);
    assertOnlyLogUrlIsUrl(record, label);
  }
  // Every JSON line this tick emitted: any release field present must be a
  // strict token, and no hostile input appears anywhere.
  for (const line of h.logs) {
    if (!line.startsWith("{")) continue;
    const record = JSON.parse(line) as Record<string, unknown>;
    if ("release" in record) {
      assert.ok(
        typeof record["release"] === "string" && SHA_OR_UNKNOWN.test(record["release"]),
        `release field is not a strict token in: ${line}`,
      );
    }
  }
  assertNoEcho(h.logs, ["hunter2", "db.internal", hostileRevision]);
});
